@contextlib.contextmanager
def temporarily(mapping, key, value):
    missing = key not in mapping
    previous = mapping.get(key)
    mapping[key] = value
    try:
        yield mapping
    finally:
        if missing:
            mapping.pop(key, None)
        else:
            mapping[key] = previous

