import functools


def retry(times, delays):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            wait = 1
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except Exception:
                    if attempt == times:
                        raise
                    delays.append(wait)
                    wait *= 2
        return wrapper
    return decorator

def dedupe(rows, key):
